import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';

const GATE = resolve('scripts/enforce-quality.sh');

// Fixture strings below are built by concatenation (e.g. 'debug' + 'ger') so
// this test file's own source never spells out, contiguously, the tokens the
// gate looks for - otherwise committing this file would trip the gate it
// tests.
const JS_DEBUGGER = 'debug' + 'ger;';
const PY_BREAKPOINT = 'break' + 'point()';
const PY_IMPORT_PDB = 'import ' + 'pd' + 'b';
const PY_PDB_TRACE = 'pd' + 'b.set_trace()';
const RB_BINDING_PRY = 'bind' + 'ing.pry';
const RB_BYEBUG = 'bye' + 'bug';
const CONFLICT_START = '<'.repeat(7) + ' HEAD';
const CONFLICT_END = '>'.repeat(7) + ' feature';
const JS_CONSOLE_LOG = 'conso' + 'le.log("hi");';
const PY_PRINT = 'pri' + 'nt("hi")';

function makeRepo() {
  const dir = mkdtempSync(join(tmpdir(), 'quality-gate-'));
  execFileSync('git', ['init', '-q'], { cwd: dir });
  return dir;
}

function stage(dir, name, content) {
  writeFileSync(join(dir, name), content);
  execFileSync('git', ['add', name], { cwd: dir });
}

function commitStaged(dir) {
  execFileSync(
    'git',
    ['-c', 'user.email=test@example.com', '-c', 'user.name=test', '-c', 'commit.gpgsign=false', 'commit', '-q', '-m', 'base'],
    { cwd: dir },
  );
}

function runGate(dir, env = {}) {
  try {
    const stdout = execFileSync('bash', [GATE], { cwd: dir, stdio: 'pipe', env: { ...process.env, ...env } });
    return { status: 0, output: stdout.toString() };
  } catch (err) {
    return {
      status: err.status,
      output: `${err.stdout ?? ''}${err.stderr ?? ''}`,
    };
  }
}

test('the gate is wired into the pre-commit hook', () => {
  assert.match(readFileSync('.githooks/pre-commit', 'utf8'), /enforce-quality\.sh/u);
});

test('the gate runs and reports its own exit status', () => {
  // Exercised rather than read: a gate nobody executes is a gate nobody has.
  const run = () => execFileSync('bash', ['scripts/enforce-quality.sh'], { stdio: 'pipe' });
  assert.doesNotThrow(run);
});

test('an empty staged diff passes', () => {
  const dir = makeRepo();
  try {
    const { status } = runGate(dir);
    assert.equal(status, 0);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('a clean addition passes with no output', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'app.js', 'function add(a, b) {\n  return a + b;\n}\n');
    const { status, output } = runGate(dir);
    assert.equal(status, 0);
    assert.equal(output.trim(), '');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

const blockingCases = [
  ['a JS debugger statement', 'app.js', `function f() {\n  ${JS_DEBUGGER}\n}\n`, `${JS_DEBUGGER.slice(0, -1)} statement`],
  ['a Python breakpoint() call', 'app.py', `def f():\n    ${PY_BREAKPOINT}\n`, `${PY_BREAKPOINT} call`],
  ['an import pdb', 'app.py', `${PY_IMPORT_PDB}\n`, PY_IMPORT_PDB],
  ['a pdb.set_trace() call', 'app.py', `${PY_PDB_TRACE}\n`, `${PY_PDB_TRACE} call`],
  ['a binding.pry', 'app.rb', `def f\n  ${RB_BINDING_PRY}\nend\n`, RB_BINDING_PRY],
  ['a byebug call', 'app.rb', `def f\n  ${RB_BYEBUG}\nend\n`, `${RB_BYEBUG} call`],
];

for (const [label, filename, content, expectedLabel] of blockingCases) {
  test(`blocks a commit that adds ${label}`, () => {
    const dir = makeRepo();
    try {
      stage(dir, filename, content);
      const { status, output } = runGate(dir);
      assert.equal(status, 1);
      assert.match(output, /^BLOCK /mu);
      assert.ok(
        output.includes(expectedLabel),
        `expected output to name the reason "${expectedLabel}", got:\n${output}`,
      );
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
}

test('blocks a commit that adds unresolved merge-conflict markers', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'app.txt', `${CONFLICT_START}\nours\n=======\ntheirs\n${CONFLICT_END}\n`);
    const { status, output } = runGate(dir);
    assert.equal(status, 1);
    const blockLines = output.split('\n').filter((l) => l.startsWith('BLOCK'));
    assert.equal(blockLines.length, 2);
    assert.ok(blockLines.every((l) => l.includes('unresolved merge marker')));
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('reports, but does not block, a console.log call', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'app.js', `function f() {\n  ${JS_CONSOLE_LOG}\n}\n`);
    const { status, output } = runGate(dir);
    assert.equal(status, 0);
    assert.match(output, /^WARN /mu);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('reports, but does not block, a print() call', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'app.py', `def f():\n    ${PY_PRINT}\n`);
    const { status, output } = runGate(dir);
    assert.equal(status, 0);
    assert.match(output, /^WARN /mu);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('only scans added lines: removing a debug statement does not block', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'app.js', `function f() {\n  ${JS_DEBUGGER}\n}\n`);
    commitStaged(dir);
    stage(dir, 'app.js', 'function f() {\n}\n');
    const { status, output } = runGate(dir);
    assert.equal(status, 0, `expected removing a debug statement not to block, got:\n${output}`);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('EOS_BYPASS_CLEANUP=1 turns a block into a pass', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'app.js', `function f() {\n  ${JS_DEBUGGER}\n}\n`);
    const blocked = runGate(dir);
    assert.equal(blocked.status, 1);

    const bypassed = runGate(dir, { EOS_BYPASS_CLEANUP: '1' });
    assert.equal(bypassed.status, 0);
    assert.match(bypassed.output, /BYPASSED/u);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('the gate does not block a commit of its own source', () => {
  const dir = makeRepo();
  try {
    stage(dir, 'enforce-quality.sh', readFileSync(GATE, 'utf8'));
    const { status, output } = runGate(dir);
    assert.equal(status, 0, `gate blocked its own source:\n${output}`);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

